(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var editingId = null;

  var dom = {
    newTodoInput: null,
    todoList: null,
    toggleAll: null,
    clearCompleted: null,
    todoCount: null,
    main: null,
    footer: null
  };

  // ---------------------------------------------------------------------------
  // Storage
  // ---------------------------------------------------------------------------

  // Storage wrapper that works with both real localStorage and test environments
  var _storage = {
    getItem: function(k) {
      try {
        return localStorage.getItem(k);
      } catch(e) {
        return null;
      }
    },
    setItem: function(k, v) {
      try {
        localStorage.setItem(k, v);
      } catch(e) {
        // Silently fail in test environments
      }
    }
  };

  function save() {
    _storage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function load() {
    var raw = _storage.getItem(STORAGE_KEY);
    todos = raw ? JSON.parse(raw) : [];
  }

  // ---------------------------------------------------------------------------
  // Todo operations
  // ---------------------------------------------------------------------------

  /** @planks("the user types {string} in the new todo input and presses Enter") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({
      id: Date.now(),
      title: trimmed,
      completed: false
    });
    save();
  }

  /** @planks("the user toggles the {string} todo checkbox") */
  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
  }

  /** @planks("the user clicks the toggle all checkbox") */
  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    save();
  }

  /** @planks("the user clears the edit input and presses Enter") */
  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
  }

  /** @planks("the user types {string} in the edit input and presses Enter") */
  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    if (!trimmed) {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    save();
  }

  /** @planks("the user clicks the clear completed button") */
  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
  }

  // ---------------------------------------------------------------------------
  // Rendering
  // ---------------------------------------------------------------------------

  function getVisibleTodos() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') {
      return todos.filter(function (t) { return !t.completed; });
    } else if (hash === '#/completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  function render() {
    var visible = getVisibleTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    var totalCount = todos.length;

    // Render todo list
    dom.todoList.innerHTML = '';
    visible.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (editingId === todo.id) li.classList.add('editing');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      dom.todoList.appendChild(li);
    });

    // Counter
    var itemText = activeCount === 1 ? 'item' : 'items';
    dom.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';

    // Toggle all
    dom.toggleAll.checked = totalCount > 0 && activeCount === 0;

    // Visibility
    if (totalCount === 0) {
      dom.main.classList.add('hidden');
      dom.footer.classList.add('hidden');
    } else {
      dom.main.classList.remove('hidden');
      dom.footer.classList.remove('hidden');
    }

    // Filter links
    var hash = window.location.hash || '#/';
    var links = document.querySelectorAll('.filters a');
    links.forEach(function (link) {
      link.classList.remove('selected');
      if (link.getAttribute('href') === hash) {
        link.classList.add('selected');
      }
    });

    // Clear completed visibility
    dom.clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // ---------------------------------------------------------------------------
  // Event handlers
  // ---------------------------------------------------------------------------

  function setupEventListeners() {
    // New todo input
    dom.newTodoInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        addTodo(dom.newTodoInput.value);
        dom.newTodoInput.value = '';
        render();
      }
    });

    // Todo list delegation
    dom.todoList.addEventListener('change', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = parseInt(li.dataset.id, 10);

      if (e.target.classList.contains('toggle')) {
        toggleTodo(id);
        render();
      }
    });

    dom.todoList.addEventListener('click', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = parseInt(li.dataset.id, 10);

      if (e.target.classList.contains('destroy')) {
        destroyTodo(id);
        render();
      }
    });

    dom.todoList.addEventListener('dblclick', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = parseInt(li.dataset.id, 10);

      if (e.target.tagName === 'LABEL') {
        editingId = id;
        render();
        var editInput = li.querySelector('.edit');
        if (editInput) editInput.focus();
      }
    });

    dom.todoList.addEventListener('keydown', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = parseInt(li.dataset.id, 10);

      if (e.target.classList.contains('edit')) {
        if (e.keyCode === ENTER_KEY) {
          editTodo(id, e.target.value);
          editingId = null;
          render();
        } else if (e.keyCode === ESCAPE_KEY) {
          editingId = null;
          render();
        }
      }
    });

    dom.todoList.addEventListener('blur', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        if (!li) return;
        var id = parseInt(li.dataset.id, 10);
        editTodo(id, e.target.value);
        editingId = null;
        render();
      }
    }, true);

    // Toggle all
    dom.toggleAll.addEventListener('change', function () {
      toggleAll();
      render();
    });

    // Clear completed
    dom.clearCompleted.addEventListener('click', function () {
      clearCompleted();
      render();
    });

    // Filter links
    document.querySelector('.filters').addEventListener('click', function (e) {
      if (e.target.tagName === 'A') {
        window.location.hash = e.target.getAttribute('href');
      }
    });

    // Hash change
    window.addEventListener('hashchange', function () {
      render();
    });
  }

  // ---------------------------------------------------------------------------
  // Init
  // ---------------------------------------------------------------------------

  function init() {
    dom.newTodoInput = document.querySelector('.new-todo');
    dom.todoList = document.querySelector('.todo-list');
    dom.toggleAll = document.querySelector('.toggle-all');
    dom.clearCompleted = document.querySelector('.clear-completed');
    dom.todoCount = document.querySelector('.todo-count');
    dom.main = document.querySelector('.main');
    dom.footer = document.querySelector('.footer');

    load();
    setupEventListeners();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

// Shared localStorage that persists across Window instances
const sharedLocalStorage = {};

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);

    // SHARED localStorage: happy-dom creates a new localStorage per Window instance, so
    // persistence across reloads is broken. Bridge the gap by making the localStorage persist.
    // Copy shared storage into this window's localStorage before the app loads
    const origLS = w.localStorage;
    for (const k of Object.keys(sharedLocalStorage)) {
      origLS.setItem(k, sharedLocalStorage[k]);
    }
    // Patch setItem and removeItem to sync back to shared storage
    const origSetItem = origLS.setItem.bind(origLS);
    origLS.setItem = function(k, v) {
      sharedLocalStorage[k] = v;
      origSetItem(k, v);
    };
    const origRemoveItem = origLS.removeItem.bind(origLS);
    origLS.removeItem = function(k) {
      delete sharedLocalStorage[k];
      origRemoveItem(k);
    };

    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () {
  // Clear shared storage for clean scenario isolation
  for (const k of Object.keys(sharedLocalStorage)) {
    delete sharedLocalStorage[k];
  }
  this.loadApp();
});

// Sync localStorage back to shared storage after each scenario, then dispose
After(async function () {
  if (this.window && this.window.localStorage) {
    const ls = this.window.localStorage;
    for (let i = 0; i < ls.length; i++) {
      const k = ls.key(i);
      sharedLocalStorage[k] = ls.getItem(k);
    }
  }
  await this.disposeApp();
});

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getNewTodoInput(doc) {
  return doc.querySelector('.new-todo');
}

function getTodoItems(doc) {
  return Array.from(doc.querySelectorAll('.todo-list li'));
}

function getTodoByTitle(doc, title) {
  return getTodoItems(doc).find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
}

function getToggleAllCheckbox(doc) {
  return doc.querySelector('.toggle-all');
}

function getClearCompletedButton(doc) {
  return doc.querySelector('.clear-completed');
}

function getEditInput(doc) {
  return doc.querySelector('.todo-list li.editing .edit');
}

function getFilterLink(doc, filter) {
  const links = doc.querySelectorAll('.filters a');
  return Array.from(links).find(a => a.textContent.trim() === filter);
}

function getCounterElement(doc) {
  return doc.querySelector('.todo-count');
}

function getMainSection(doc) {
  return doc.querySelector('.main');
}

function getFooter(doc) {
  return doc.querySelector('.footer');
}

function createTodo(doc, title) {
  const input = getNewTodoInput(doc);
  input.value = title;
  const event = new doc.defaultView.KeyboardEvent('keydown', {
    key: 'Enter',
    code: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);
}

function createCompletedTodo(doc, title) {
  createTodo(doc, title);
  const todo = getTodoByTitle(doc, title);
  if (todo) {
    const checkbox = todo.querySelector('.toggle');
    checkbox.checked = true;
    checkbox.dispatchEvent(new doc.defaultView.Event('change', { bubbles: true }));
  }
}

function toggleTodo(doc, title) {
  const todo = getTodoByTitle(doc, title);
  if (todo) {
    const checkbox = todo.querySelector('.toggle');
    checkbox.checked = !checkbox.checked;
    checkbox.dispatchEvent(new doc.defaultView.Event('change', { bubbles: true }));
  }
}

function doubleClickTodoLabel(doc, title) {
  const todo = getTodoByTitle(doc, title);
  if (todo) {
    const label = todo.querySelector('label');
    label.dispatchEvent(new doc.defaultView.Event('dblclick', { bubbles: true }));
  }
}

function typeInEditInput(doc, text) {
  const input = getEditInput(doc);
  if (input) {
    input.value = text;
    input.dispatchEvent(new doc.defaultView.Event('input', { bubbles: true }));
  }
}

function pressEnterOnEditInput(doc) {
  const input = getEditInput(doc);
  if (input) {
    input.dispatchEvent(new doc.defaultView.KeyboardEvent('keydown', {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    }));
  }
}

function pressEscapeOnEditInput(doc) {
  const input = getEditInput(doc);
  if (input) {
    input.dispatchEvent(new doc.defaultView.KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true
    }));
  }
}

function blurEditInput(doc) {
  const input = getEditInput(doc);
  if (input) {
    input.dispatchEvent(new doc.defaultView.Event('blur', { bubbles: true }));
  }
}

function clearEditInputAndPressEnter(doc) {
  const input = getEditInput(doc);
  if (input) {
    input.value = '';
    input.dispatchEvent(new doc.defaultView.Event('input', { bubbles: true }));
    input.dispatchEvent(new doc.defaultView.KeyboardEvent('keydown', {
      key: 'Enter',
      code: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    }));
  }
}

function clearEditInputAndPressEnterOnTodo(doc, title) {
  const todo = getTodoByTitle(doc, title);
  if (todo) {
    const label = todo.querySelector('label');
    label.dispatchEvent(new doc.defaultView.Event('dblclick', { bubbles: true }));
    const input = getEditInput(doc);
    if (input) {
      input.value = '';
      input.dispatchEvent(new doc.defaultView.Event('input', { bubbles: true }));
      input.dispatchEvent(new doc.defaultView.KeyboardEvent('keydown', {
        key: 'Enter',
        code: 'Enter',
        keyCode: 13,
        which: 13,
        bubbles: true
      }));
    }
  }
}

function clickToggleAll(doc) {
  const toggleAll = getToggleAllCheckbox(doc);
  if (toggleAll) {
    toggleAll.checked = !toggleAll.checked;
    toggleAll.dispatchEvent(new doc.defaultView.Event('change', { bubbles: true }));
  }
}

function clickClearCompleted(doc) {
  const button = getClearCompletedButton(doc);
  if (button) {
    button.click();
  }
}

function reloadPage(world) {
  world.disposeApp();
  world.loadApp();
}

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given('the app is loaded with no todos', function () {
  // App is already loaded by the Before hook; no todos exist by default
});

Given('the app has a todo {string}', function (title) {
  createTodo(this.document, title);
});

Given('the app has a completed todo {string}', function (title) {
  createCompletedTodo(this.document, title);
});

Given('the app has todos {string} and {string}', function (title1, title2) {
  createTodo(this.document, title1);
  createTodo(this.document, title2);
});

Given('the app has completed todos {string} and {string}', function (title1, title2) {
  createCompletedTodo(this.document, title1);
  createCompletedTodo(this.document, title2);
});

Given('the app has a todo {string} and a completed todo {string}', function (activeTitle, completedTitle) {
  createTodo(this.document, activeTitle);
  createCompletedTodo(this.document, completedTitle);
});

Given('the user navigates to {string}', function (hash) {
  this.navigate(hash);
  // Manually trigger render after navigation
  this.window.eval('window.dispatchEvent(new Event("hashchange"))');
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When('the user types {string} in the new todo input and presses Enter', function (text) {
  createTodo(this.document, text);
});

When('the user toggles the {string} todo checkbox', function (title) {
  toggleTodo(this.document, title);
});

When('the user double-clicks the {string} todo label', function (title) {
  doubleClickTodoLabel(this.document, title);
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  typeInEditInput(this.document, text);
  pressEnterOnEditInput(this.document);
});

When('the user types {string} in the edit input and blurs', function (text) {
  typeInEditInput(this.document, text);
  blurEditInput(this.document);
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  typeInEditInput(this.document, text);
  pressEscapeOnEditInput(this.document);
});

When('the user clears the edit input and presses Enter', function () {
  clearEditInputAndPressEnter(this.document);
});

When('the user clears the edit input and presses Enter on the {string} todo', function (title) {
  clearEditInputAndPressEnterOnTodo(this.document, title);
});

When('the user clicks the clear completed button', function () {
  clickClearCompleted(this.document);
});

When('the user clicks the toggle all checkbox', function () {
  clickToggleAll(this.document);
});

When('the page is reloaded', function () {
  // Save current localStorage state to shared storage
  const ls = this.window.localStorage;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    // The sharedLocalStorage is already being synced via the proxy in world.js
  }
  // Reload the page - the world.js loadApp will copy sharedLocalStorage to new window
  reloadPage(this);
});

// ---------------------------------------------------------------------------
// Then steps
// ---------------------------------------------------------------------------

Then('a todo with title {string} appears in the todo list', function (title) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo, `Expected todo with title "${title}" to exist`).to.not.be.undefined;
});

Then('the new todo input is empty', function () {
  const input = getNewTodoInput(this.document);
  expect(input.value).to.equal('');
});

Then('the todo count shows {string}', function (expected) {
  const counter = getCounterElement(this.document);
  expect(counter.textContent.trim()).to.equal(expected);
});

Then('the todo list is empty', function () {
  const items = getTodoItems(this.document);
  expect(items).to.have.length(0);
});

Then('the new todo input has focus', function () {
  const input = getNewTodoInput(this.document);
  expect(input === this.document.activeElement).to.be.true;
});

Then('the todo list shows {int} todos', function (count) {
  const items = getTodoItems(this.document);
  expect(items).to.have.length(count);
});

Then('the {string} todo has class {string}', function (title, className) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo, `Expected todo "${title}" to exist`).to.not.be.undefined;
  expect(todo.classList.contains(className)).to.be.true;
});

Then('the {string} todo does not have class {string}', function (title, className) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo, `Expected todo "${title}" to exist`).to.not.be.undefined;
  expect(todo.classList.contains(className)).to.be.false;
});

Then('the {string} todo does not exist', function (title) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo).to.be.undefined;
});

Then('the todo {string} does not exist', function (title) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo).to.be.undefined;
});

Then('the todo {string} is visible', function (title) {
  const todo = getTodoByTitle(this.document, title);
  expect(todo, `Expected todo "${title}" to exist`).to.not.be.undefined;
  const style = this.window.getComputedStyle(todo);
  expect(style.display).to.not.equal('none');
});

Then('the todo {string} is not visible', function (title) {
  const todo = getTodoByTitle(this.document, title);
  if (todo) {
    const style = this.window.getComputedStyle(todo);
    expect(style.display).to.equal('none');
  }
});

Then('the clear completed button is hidden', function () {
  const button = getClearCompletedButton(this.document);
  const style = this.window.getComputedStyle(button);
  expect(style.display).to.equal('none');
